<?php
declare(strict_types=1);
namespace MMIG46\Services;
use Dompdf\Dompdf;
use Dompdf\Options;
use MMIG46\Core\Security;

final class InvoicePdf
{
    public static function render(array $invoice,array $items,array $issuer,bool $draft=false): string
    {
        if(!class_exists(Dompdf::class))throw new \RuntimeException('Dompdf ist nicht installiert. Bitte composer install ausführen.');
        $en=($invoice['language']??'de')==='en'; $e=static fn($v)=>Security::e((string)$v);
        $money=static fn(int $v)=>number_format($v/100,2,$en?'.':',',$en?',':'.').' EUR';
        $date=static fn($v)=>$v?date($en?'Y-m-d':'d.m.Y',strtotime((string)$v)):'';
        $title=$draft?($en?'DRAFT – not an invoice':'ENTWURF – keine Rechnung'):(($invoice['status']??'')==='cancelled'?($en?'CANCELLED INVOICE':'STORNIERTE RECHNUNG'):($en?'INVOICE':'RECHNUNG'));
        $rows=''; foreach($items as $item){$qty=number_format(((int)$item['quantity_millis'])/1000,3,$en?'.':',','');$tax=number_format(((int)$item['tax_rate_basis_points'])/100,2,$en?'.':',','');$rows.='<tr><td>'.$e($item['position_no']).'</td><td>'.$e($item['description']).'</td><td class="r">'.$qty.' '.$e($item['unit']).'</td><td class="r">'.$money((int)$item['unit_net_cents']).'</td><td class="r">'.$tax.' %</td><td class="r">'.$money((int)$item['line_net_cents']).'</td></tr>';}
        $taxRows='';$byTax=[];foreach($items as $item){$rate=(int)$item['tax_rate_basis_points'];$byTax[$rate]=($byTax[$rate]??0)+(int)$item['line_tax_cents'];}foreach($byTax as $rate=>$amount)$taxRows.='<tr><td>'.($en?'VAT':'Umsatzsteuer').' '.number_format($rate/100,2,$en?'.':',','').' %</td><td class="r">'.$money($amount).'</td></tr>';
        $issuerAddress=implode('<br>',array_map($e,array_filter([$issuer['invoice_issuer_name']??'', $issuer['invoice_issuer_street']??'',trim(($issuer['invoice_issuer_postal_code']??'').' '.($issuer['invoice_issuer_city']??'')),$issuer['invoice_issuer_country']??''])));
        $recipient=implode('<br>',array_map($e,array_filter([$invoice['recipient_name']??'',$invoice['recipient_street']??'',trim(($invoice['recipient_postal_code']??'').' '.($invoice['recipient_city']??'')),$invoice['recipient_country']??''])));
        $html='<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:18mm}body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:10pt}.head{border-bottom:3px solid #203a63;padding-bottom:10px}.brand{font-size:22pt;font-weight:bold;color:#203a63}.badge{margin:12px 0;padding:8px;background:#f0f3f7;color:#8b1e2d;font-weight:bold;text-align:center}.columns{width:100%;margin:22px 0}.columns td{width:50%;vertical-align:top}.meta{margin:15px 0}.items{width:100%;border-collapse:collapse}.items th{background:#203a63;color:#fff;padding:7px}.items td{padding:7px;border-bottom:1px solid #ccd3dc}.r{text-align:right}.totals{margin-left:auto;margin-top:15px;width:45%;border-collapse:collapse}.totals td{padding:4px}.gross{font-weight:bold;border-top:2px solid #203a63}.footer{position:fixed;bottom:-8mm;font-size:8pt;color:#586270}</style></head><body><div class="head"><div class="brand">'.$e($issuer['invoice_issuer_name']??'MMIG46 e.V.').'</div><div>'.$e($title).'</div></div>'.(($draft||($invoice['status']??'')==='cancelled')?'<div class="badge">'.$e($title).'</div>':'').'<table class="columns"><tr><td>'.$issuerAddress.'</td><td>'.$recipient.'</td></tr></table><table class="meta"><tr><td><strong>'.($en?'Invoice number':'Rechnungsnummer').':</strong></td><td>'.$e($invoice['invoice_number']??($en?'assigned upon finalization':'wird bei Finalisierung vergeben')).'</td></tr><tr><td><strong>'.($en?'Invoice date':'Rechnungsdatum').':</strong></td><td>'.$date($invoice['invoice_date']??'').'</td></tr><tr><td><strong>'.($en?'Service period':'Leistungszeitraum').':</strong></td><td>'.$date($invoice['service_start']??'').' – '.$date($invoice['service_end']??'').'</td></tr><tr><td><strong>'.($en?'Due date':'Zahlungsziel').':</strong></td><td>'.$date($invoice['due_date']??'').'</td></tr><tr><td><strong>'.($en?'Reason':'Anlass').':</strong></td><td>'.$e($invoice['occasion']??'').'</td></tr></table>'.(($invoice['status']??'')==='cancelled'?'<p><strong>'.($en?'Cancellation reason':'Stornierungsgrund').':</strong> '.$e($invoice['cancellation_reason']??'').'</p>':'').'<table class="items"><thead><tr><th>#</th><th>'.($en?'Description':'Bezeichnung').'</th><th>'.($en?'Quantity':'Menge').'</th><th>'.($en?'Unit price':'Einzelpreis').'</th><th>'.($en?'VAT':'USt.').'</th><th>'.($en?'Net':'Netto').'</th></tr></thead><tbody>'.$rows.'</tbody></table><table class="totals"><tr><td>'.($en?'Net total':'Nettosumme').'</td><td class="r">'.$money((int)$invoice['net_cents']).'</td></tr>'.$taxRows.'<tr class="gross"><td>'.($en?'Total':'Gesamtbetrag').'</td><td class="r">'.$money((int)$invoice['gross_cents']).'</td></tr></table><p>'.$e($invoice['notes']??'').'</p><p><strong>IBAN:</strong> '.$e($issuer['invoice_iban']??'').' &nbsp; <strong>BIC:</strong> '.$e($issuer['invoice_bic']??'').'<br><strong>'.($en?'Tax number / VAT ID':'Steuernummer / USt-ID').':</strong> '.$e($issuer['invoice_tax_number_or_vat_id']??'').'</p><div class="footer">'.$e($issuer[$en?'invoice_footer_note_en':'invoice_footer_note_de']??'').'</div></body></html>';
        $options=new Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('defaultFont','DejaVu Sans');
        $dompdf=new Dompdf($options);$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4');$dompdf->render();return $dompdf->output();
    }
}
